import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val a = IntArray(n)
    var count = 0

    for (i in 0 until n) {
        a[i] = scanner.nextInt()
        count += a[i]
    }

    var temp = a[0]
    for (i in 0 until n) {
        temp = maxOf(temp, a[i])
    }

    var ans = 0
    var i = 0
    while (true) {
        val k = temp + i
        if (n * k - count > count) {
            ans = k
            break
        }
        i++
    }

    print(ans)
}

